# ruff: noqa: A005  # `ds.util.http` is namespaced under ds.util, so it never shadows stdlib
# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the one way this repo sends an HTTP request to an outside site: plain httpx2
# underneath, plus one standard log record per request (ds.util.logging.log_call) with the
# full request (secrets filtered), what came back and how long it took.
# Usage: `with http.request("GET", url, source="smashtube", params=p) as (resp, call):`, then
#   read `resp` and add what only the caller knows, eg `call["rows"] = 10`. Async code uses
#   `async with http.arequest(...)` the same way.
# ---------------------------------------------------------------------------
#
# Only sending and logging happen here. Retries, rate limits and caching are per-site
# decisions and stay with each source (caching needs the user's approval first, see
# "Caching Policy" in .agents/agents.md). Tests can still fake the transport
# (httpx2.MockTransport via `client=`) or record with VCR: this is httpx2 all the way down.
from __future__ import annotations

import json
import re
import shlex
import threading
from collections import Counter
from collections.abc import AsyncIterator, Iterator, Mapping
from contextlib import asynccontextmanager, contextmanager
from typing import Any

import httpx2

from ds.util.logging import log_call

__all__ = [
    "DEFAULT_TIMEOUT",
    "FILTERED",
    "SECRET_HEADERS",
    "arequest",
    "curl_command",
    "filter_headers",
    "request",
]

DEFAULT_TIMEOUT = 30.0  # seconds, for requests without their own client
# Header names whose values never reach a log record (compared lowercased). Add new ones here.
SECRET_HEADERS = frozenset(
    {"authorization", "proxy-authorization", "apikey", "x-api-key", "api-key", "cookie", "set-cookie"},
)
FILTERED = "[filtered]"
MAX_BODY_CHARS = 2000  # request body kept in the record
MAX_ERROR_CHARS = 300  # response body kept when the site answers with an error
_ERROR_STATUS = 400
# response headers worth a field: who answered, did a bot check step in, how long to wait
_RESPONSE_HEADERS = {
    "cf-ray": "cf_ray",
    "cf-mitigated": "cf_mitigated",
    "x-vercel-mitigated": "vercel_mitigated",
    "retry-after": "retry_after",
}
# headers curl sets itself, left out of `curl_command`
_CURL_SKIP = frozenset({"host", "content-length", "connection", "accept-encoding", "accept", "user-agent"})

_in_flight: Counter[str] = Counter()
_in_flight_lock = threading.Lock()


def filter_headers(headers: Mapping[str, str]) -> dict[str, str]:
    """Headers with every secret value replaced ('Bearer' is kept, the token is not)."""
    shown = {}
    for name, value in headers.items():
        kept = value
        if name.lower() in SECRET_HEADERS:
            scheme, _, _ = value.partition(" ")
            kept = f"{scheme} {FILTERED}" if scheme.lower() in {"bearer", "basic", "token"} else FILTERED
        shown[name.lower()] = kept
    return shown


def _body(content: bytes) -> Any:
    """A request body for the record: parsed JSON when it is JSON, else (cut) text."""
    if not content:
        return None
    text = content.decode("utf-8", errors="replace")
    try:
        return json.loads(text) if len(text) <= MAX_BODY_CHARS else text[:MAX_BODY_CHARS] + "…"
    except ValueError:
        return text[:MAX_BODY_CHARS]


def _request_fields(method: str, url: str, kwargs: dict[str, Any]) -> dict[str, Any]:
    """What is known before sending: enough to name a request that never got an answer."""
    full = httpx2.URL(url, params=kwargs.get("params"))
    return {"method": method.upper(), "url": str(full), "params": dict(full.params) or None}


def _response_fields(resp: httpx2.Response) -> dict[str, Any]:
    request = resp.request
    fields: dict[str, Any] = {
        "url": str(request.url) if not resp.history else str(resp.history[0].request.url),
        "request_headers": filter_headers(request.headers),
        "request_body": _body(request.content),
        "status": resp.status_code,
        "content_type": resp.headers.get("content-type", "").split(";")[0] or None,
        "bytes": len(resp.content),
    }
    if resp.history:
        fields["final_url"] = str(resp.url)
        fields["redirects"] = len(resp.history)
    fields |= {key: resp.headers[name] for name, key in _RESPONSE_HEADERS.items() if name in resp.headers}
    if resp.status_code >= _ERROR_STATUS:
        fields["error_body"] = resp.text[:MAX_ERROR_CHARS]
    return fields


@contextmanager
def _counting(source: str) -> Iterator[int]:
    """How many requests to `source` are in flight, this one included."""
    with _in_flight_lock:
        _in_flight[source] += 1
        count = _in_flight[source]
    try:
        yield count
    finally:
        with _in_flight_lock:
            _in_flight[source] -= 1


@contextmanager
def request(
    method: str,
    url: str,
    *,
    source: str,
    name: str = "",
    kind: str = "http",
    fields: Mapping[str, Any] | None = None,
    client: httpx2.Client | None = None,
    **kwargs: Any,
) -> Iterator[tuple[httpx2.Response, dict[str, Any]]]:
    """Send one request and log it when the block ends; yields (response, the record's fields)

    Args:
        method: 'GET', 'POST', ...
        url: the url, without or with a query string (`params=` is merged in).
        source: who is called, eg 'smashtube' (the debug panel filters and badges by it).
        name: what the request is for, eg 'video search'.
        kind: the record's kind; 'graphql' for ds.util.graphql.
        fields: extra fields known up front, eg {'wait_ms': 12}.
        client: an httpx2.Client to reuse (its defaults apply); else a one-off request with
            DEFAULT_TIMEOUT.
        **kwargs: passed to httpx2 as is (params, json, headers, follow_redirects, ...).

    Put what only the caller knows in the yielded dict (eg `call["rows"] = len(videos)`). The
    response is not checked: call `resp.raise_for_status()` where an error status should raise.
    """
    with log_call(kind, source, name=name, **_request_fields(method, url, kwargs), **(fields or {})) as call:
        with _counting(source) as in_flight:
            call["in_flight"] = in_flight
            if client is None:
                resp = httpx2.request(method, url, timeout=kwargs.pop("timeout", DEFAULT_TIMEOUT), **kwargs)
            else:
                resp = client.request(method, url, **kwargs)
        call.update(_response_fields(resp))
        yield resp, call


@asynccontextmanager
async def arequest(
    method: str,
    url: str,
    *,
    source: str,
    name: str = "",
    kind: str = "http",
    fields: Mapping[str, Any] | None = None,
    client: httpx2.AsyncClient | None = None,
    **kwargs: Any,
) -> AsyncIterator[tuple[httpx2.Response, dict[str, Any]]]:
    """`request` for async code; `client` is an httpx2.AsyncClient (eg one per paged lookup)"""
    with log_call(kind, source, name=name, **_request_fields(method, url, kwargs), **(fields or {})) as call:
        with _counting(source) as in_flight:
            call["in_flight"] = in_flight
            if client is None:
                async with httpx2.AsyncClient(timeout=kwargs.pop("timeout", DEFAULT_TIMEOUT)) as own:
                    resp = await own.request(method, url, **kwargs)
            else:
                resp = await client.request(method, url, **kwargs)
        call.update(_response_fields(resp))
        yield resp, call


def _env_name(header: str) -> str:
    return re.sub(r"\W", "_", header).upper()


def curl_command(record: Mapping[str, Any]) -> str:
    """A record of `request` / `arequest` as a curl command that sends the same request

    Filtered secrets become shell variables, eg `Authorization: Bearer $AUTHORIZATION`; set
    them before running it. '' when the record has no url.
    """
    if not record.get("url"):
        return ""
    lines = [f"curl -sS -X {record.get('method', 'GET')} {shlex.quote(str(record['url']))}"]
    if record.get("redirects"):
        lines.append("-L")
    for header, value in (record.get("request_headers") or {}).items():
        if header in _CURL_SKIP:
            continue
        line = f"{header}: {str(value).replace(FILTERED, '$' + _env_name(header))}"
        # double quotes so a $VARIABLE expands; header values here hold no other shell syntax
        lines.append(f'-H "{line}"' if "$" in line else f"-H {shlex.quote(line)}")
    body = record.get("request_body")
    if body is not None:
        text = body if isinstance(body, str) else json.dumps(body, separators=(",", ":"), ensure_ascii=False)
        lines.append(f"--data-raw {shlex.quote(text)}")
    return " \\\n  ".join(lines)
